		&p.handle, &ticks[0])); err != nil {
		return 0, nil, err
	}
	period := p.dev.phys.TimestampPeriod
	total := time.Duration((float64(uint64(ticks[len(ticks)-1])) - float64(uint64(ticks[0]))) * period)
