	}
	mask := a.Selection()
	fmt.Printf("    selection live %%, (query tile) x (key block):\n")
	fmt.Printf("      %-6s %8s %8s %8s %8s\n", "bm\\bn", "16", "32", "64", "row")
	for _, bm := range []int{16, 32, 64} {
