8	// The QSA selection's live key blocks, compacted into a list per query tile:
9	// the dispatch that makes a prefill's attention flat in depth (P13).
10	//
11	// **What it is for.** `llm_attn_wmma.comp` skips a key block with nothing
12	// selected in it (P7), and that skip is bit-identical — an unselected cell
13	// contributes nothing to O and nothing to the row sum, so a block of them
14	// contributes nothing. What it does *not* do is stop the kernel walking every
15	// block to find out. At 64 000 cells a 16x32 tile keeps 25.9% of the (query
16	// tile, key block) pairs live (P11-7) and the other 74% are still visited:
17	// the loop stages BM*(BN/32) words of the bitmask, ORs them, and continues.
18	//
19	// That visit is not free and it is the whole slope. The staging reads one
20	// word per *row*, so a 16-row tile touches sixteen addresses `nKV/32` dwords
21	// apart — sixteen separate 64-byte lines fetched to use 128 bytes of them —
22	// and it does it once per head, because the mask is per token and the grid is
23	// (query block, head). Twenty-four heads times 128 query tiles times every
24	// block of the cache, at 8x line amplification, is **6.3 GB a layer at
25	// 64 000 cells** and twice that at 128k. It is ~30% of `attn.attn` there, and
26	// it is the difference between the 9.8 TFLOP/s of useful work the kernel gets
27	// at depth and the 16.0 it gets at depth zero.
28	//
29	// So the OR moves here, once, for all twenty-four heads, and what the
30	// attention kernel reads instead is the answer: the ascending indices of the
31	// blocks that have anything in them. **The live count is flat in depth** —
32	// 515 blocks at 32 000 cells and 518 at 64 000, because QSA names 2051 cells
33	// however deep the cache is and they cluster — so a kernel that iterates the
34	// list rather than the axis is flat in depth too.
35	//
36	// **This kernel's own traffic is the mask read once instead of twenty-four
37	// times, and coalesced instead of strided.** Lane `b` takes block `b`, so
38	// consecutive lanes read consecutive words of one row and a wave's read of a
39	// row is one contiguous run. Per query tile it is `nBlocks * BM` words —
40	// 278 KB at 128k — and across twelve layers of a 2048-token batch that is
41	// ~430 MB against the ~75 GB the attention kernels were fetching to learn
42	// the same thing.
43	//
44	// **It changes no arithmetic.** The list is ascending and holds exactly the
45	// blocks the skip would not have skipped, so the attention kernel visits the
46	// same blocks in the same order and folds the same partial softmaxes the same
47	// way. It is bit-identical rather than close, and
48	// TestAttnGPUBlockListDoesNotChangeTheAnswer is the gate that says so.
49	//
50	// **Prefill only.** The split decode kernel (P8) strides *absolute* key
51	// blocks precisely so that a slice does not depend on how the prompt was
52	// chunked; striding a compacted list instead would put the slice boundaries
53	// somewhere that does depend on it, which is the bug L7a's gate exists to
54	// catch. The list is built when the graph is not splitting, which is every
55	// pass wider than one query tile.
56	
57	#include "llm_common.glsl"
58	
59	#ifndef BM
60	#define BM 16       // query rows a tile, the consuming kernel's QT * 16
61	#endif
62	#ifndef BN
63	#define BN 32       // cells a key block, the consuming kernel's KTIL * 16
64	#endif
65	#ifndef WG
66	#define WG 256
67	#endif
68	
69	// Mask words a row a key block, and which bits of the first of them the
70	// block covers. **BN may be narrower than a word**: a 16-cell key block
71	// (KTIL=1) is half of one, and ORing the whole word would call a block live
72	// because its neighbour has something in it.
73	#define BWORDS ((BN + 31) / 32)
74	#define MAXWAVES 16
75	
76	layout(local_size_x = WG) in;
77	
78	// One count per wave of this chunk, and the running offset each wave's
79	// output starts at. A ballot gives a lane its position inside its own wave;
80	// these two give the wave its position inside the workgroup.
81	shared uint wcount[MAXWAVES];
82	shared uint woff[MAXWAVES];
83	// How many blocks have been emitted so far, carried across the chunks.
84	shared uint emitted;
85	
86	void main() {
87	    uint qt = gl_WorkGroupID.x;
88	    uint q0 = qt * BM;
89	    if (q0 >= pc.tokens) {
90	        return;
91	    }
92	    uint lane = gl_LocalInvocationID.x;
93	    uint past = SEQ_PAST;
94	    uint n = past + pc.tokens;
95	
96	    // Exactly the bound the attention kernel's loop has: nothing past this
97	    // query tile's last row can be attended to, and its last row is cell
98	    // `past + q0 + BM - 1`. A block the loop would never reach must not be in
99	    // the list, because the list is what replaces the loop.
100	    uint last = min(n, past + q0 + BM);
101	    uint nb = (last + BN - 1u) / BN;
102	
103	    uint words = (pc.nKV + 31u) / 32u;
104	    uint stride = 1u + (pc.nKV + BN - 1u) / BN;
105	    uint outBase = pc.resOff + qt * stride;
106	
107	    if (lane == 0u) {
108	        emitted = 0u;
109	    }
110	    barrier();
111	
112	    for (uint b0 = 0u; b0 < nb; b0 += WG) {
113	        uint b = b0 + lane;
114	        bool live = false;
115	        if (b < nb) {
116	            // The OR down the tile's rows, which is what "any row of this key
117	            // block has any cell selected" means and is what `blkAny` was.
118	            // A pad row has no selection — llm_attn_select.comp does not run
119	            // past the prompt — and the rows are ascending, so the first one
120	            // past `tokens` ends the walk.
121	            uint cell0 = b * BN;
122	            uint w0 = cell0 >> 5u;
123	            uint keep = (BN < 32) ? (((1u << BN) - 1u) << (cell0 & 31u)) : 0xFFFFFFFFu;
124	            uint acc = 0u;
125	            for (uint r = 0u; r < BM; ++r) {
126	                uint token = q0 + r;
127	                if (token >= pc.tokens) {
128	                    break;
129	                }
130	                for (uint w = 0u; w < BWORDS; ++w) {
131	                    uint word = actu[pc.selOff + token * words + w0 + w];
132	                    acc |= (w == 0u) ? (word & keep) : word;
133	                }
134	            }
135	            live = acc != 0u;
136	        }
137	
138	        // The compaction, and it has to preserve order: the attention kernel
139	        // folds its partial softmaxes in the order it meets the blocks, so a
140	        // list that holds the same blocks in a different order is a different
141	        // rounding. A ballot is the position inside a wave and the two
142	        // shared arrays are the position of the wave.
143	        uvec4 vote = subgroupBallot(live);
144	        uint within = subgroupBallotExclusiveBitCount(vote);
145	        uint wave = gl_SubgroupID;
146	        if (subgroupElect()) {
147	            wcount[wave] = subgroupBallotBitCount(vote);
148	        }
149	        barrier();
150	        if (lane == 0u) {
151	            uint acc = emitted;
152	            for (uint w = 0u; w < gl_NumSubgroups; ++w) {
153	                woff[w] = acc;
154	                acc += wcount[w];
155	            }
156	            emitted = acc;
157	        }
158	        barrier();
159	        if (live) {
160	            actu[outBase + 1u + woff[wave] + within] = b;
161	        }
162	        barrier();
163	    }
164	
165	    if (lane == 0u) {
166	        actu[outBase] = emitted;
167	    }
