123	// TestAttnGPURungsAgree is what P13's new rungs need and the ladder never
124	// had: a correctness gate over *every* build of llm_attn_wmma.comp, not just
125	// the shipped one.
126	//
127	// The 16-cell rung (qt1_kt1) is why it exists. A key block narrower than a
128	// mask word is the first shape in this file where `base` is not a multiple of
129	// 32, so the staged bitmask slice is a *half* of a word and every `selected`
130	// bit moves by `base & 31`. Get that wrong and the kernel is still a
131	// perfectly well-formed attention — over the wrong cells — which every
132	// tolerance against llama.cpp would pass by being roughly a dense causal
133	// attention.
134	//
135	// It is a tolerance and not an equality, and it has to be: a rung is a
136	// different number of online-softmax rescales in a different order, and fp32
137	// addition is not associative. The bar is P8's, for the same reason — the
138	// dense bank this layer reads is itself 5.4e-3 rms from the f32 model.
139	func TestAttnGPURungsAgree(t *testing.T) {
140		g, tr, c, nTok, done := attnGPU4k(t)
141		defer done()
142		if !g.Sparse() {
143			t.Fatalf("the fixture is not selecting: width %d of %d cells", g.selWidth(), g.NKV())
144		}
145		src, err := tr.Get("hc_mixed-3", 0)
146		if err != nil {
147			t.Fatal(err)
148		}
149		in := src.Vals
150		_, gemm, outGemm := g.Plan()
151		g.SetSplits(1)
152		defer g.SetSplits(0)
153	
154		run := func(k AttnKernel) []float32 {
155			if err := g.SetPlan(k, gemm, outGemm); err != nil {
156				t.Fatal(err)
157			}
158			return runChunks(t, g, in, c.NEmbd, []int{nTok})
159		}
160		want := run(AttnQT1KT2)
161		for _, k := range AttnKernels() {
162			if k == AttnQT1KT2 {
163				continue
164			}
165			got := run(k)
166			var maxAbs, sum2, ref2 float64
167			for i := range got {
168				d := math.Abs(float64(got[i]) - float64(want[i]))
169				maxAbs = math.Max(maxAbs, d)
170				sum2 += d * d
171				ref2 += float64(want[i]) * float64(want[i])
172			}
173			rms := math.Sqrt(sum2 / ref2)
174			t.Logf("%-8s against qt1_kt2: rms %.3g, max abs %.3g", k, rms, maxAbs)
175			if rms > 1e-3 {
176				t.Errorf("%s: rms %.3g against the shipped rung, over the 1e-3 a reassociation "+
177					"can account for — this is a different set of cells, not a different order", k, rms)
178			}
179		}
180		if err := g.SetPlan(AttnQT1KT2, gemm, outGemm); err != nil {
181			t.Fatal(err)
182		}
183	}

